insert into kb_chunks (source, title, body) values
('rooms', 'What information is needed to request a room', 'Choose a date from today through 14 days ahead, a period, and a free room on the floor plan. Enter the attendee count, faculty name and reason. The request is sent to the department that owns the room block for approval.'),
('rooms', 'What do the room availability colours mean', 'Green means the room is free for the selected date and period. Amber means a request is pending; the department chooses which request to approve. Red means the room is booked or a scheduled class is using it. Grey or closed rooms, including stairs, cannot be selected.'),
('rooms', 'Can I cancel a room request', 'Open My room requests to see each request and its status. Use Cancel request to release a request slot. Cancelling a room request is different from a faculty member cancelling a scheduled class, which frees that room for the selected date only.'),
('rooms', 'How do I find a room for my group', 'On Book a room, choose a date and period and enter the number of attendees, then select Find me a room. Suggestions are free rooms that fit the group, ordered to favor a tight fit. Selecting a suggestion fills in the floor plan; you still need to send the room request and wait for approval.'),
('canteen', 'How do I pay for a canteen order', 'Place an order for a canteen menu and an available pickup slot to receive an order token. Pay at that canteen counter. The counter marks the order paid, the kitchen prepares it and marks it ready, and staff hand it over at pickup. The app does not take payment when the order is placed.'),
('canteen', 'Why can I not select a pickup slot', 'Pickup slots are 15 minutes long and have limited capacity. A full slot cannot be selected. A slot must start at least 15 minutes from now and end within the next 60 minutes, using Indian Standard Time.'),
('canteen', 'What happens if I do not pay before pickup', 'An order remains unpaid after it is placed. If it is not paid at the counter before its pickup slot ends, it is automatically marked forfeited and you are notified.'),
('canteen', 'When is a canteen order fully collected', 'A kitchen marks a paid order ready. At handover, staff tick off every item given to the customer; the order can only be marked collected after every item is checked.'),
('canteen', 'Can canteen staff access another canteen', 'No. Kitchen, counter and manager accounts are scoped to their assigned canteen. Kitchen staff mark paid orders ready, counter staff take payment and handle handover, and managers maintain that canteen menu and pickup slots.'),
('events', 'What details and limits apply to an event request', 'A club president requests an event for their own club. Choose a date at least 7 days ahead, a hall, expected attendance within the hall capacity, a faculty coordinator and contact details. Events must start at or after 7:00 AM, end by 11:00 PM, and last no more than 8 hours. The chosen hall cannot already have an approved event at an overlapping time.'),
('events', 'What happens after an event is submitted', 'Student affairs reviews a club event request first. They can approve it for campus director review, request changes with a note, or reject it. After student affairs approval, the campus director gives final approval or rejects it. The events department then marks approved events as calendared.'),
('events', 'How do I respond to a request for event changes', 'Open My events and find the request marked Changes requested. Read the reviewer note, update the event details as needed, and resubmit it for review. The event must still satisfy the date, time, hall capacity and scheduling rules.'),
('events', 'Which events appear on the campus calendar', 'The campus calendar shows events approved by the campus director, including events the events department has marked as calendared. Requests still awaiting review, or sent back for changes, are not calendar listings.'),
('service', 'How do I report and track a campus issue', 'Use Report an issue to describe what is broken and where it is. Choose the category and priority, and optionally attach a JPEG, PNG or WebP photo up to 5 MB. After submitting, use My service requests to follow its status and updates.'),
('service', 'Can I follow an existing service request', 'If someone has already reported the same issue, open that ticket and choose the option to follow it instead of creating a duplicate. The ticket shows how many other people are following it, and you can follow its progress from your service requests.'),
('service', 'How are service request categories routed', 'Electrical issues such as fans, lights and sockets go to Electrical; Wi-Fi, network and AV equipment issues go to IT; plumbing, furniture, cleanliness and hostel-service issues go to Hostel; and other issues go to Academic Affairs. The app suggests a category and priority from the report, but the requester supplies the issue details.'),
('service', 'What do service request priority targets mean', 'The overdue targets are measured from ticket creation until resolution: urgent is 4 hours, high is 24 hours, medium is 72 hours, and low is 7 days. The timer stops while a ticket is resolved or closed; if the requester reopens it, the unresolved time starts counting again.'),
('service', 'What do service request statuses mean', 'A ticket can be assigned to a technician, moved to in progress, then resolved. The requester can close a resolved ticket if the fix worked or reopen it if the issue remains. A requester can also close an open or reopened ticket when they no longer need help.'),
('notifications', 'How do I enable phone notifications', 'Open Notifications and turn on phone notifications, then allow permission in your browser or device settings. On iPhone, first add the app to the Home Screen and open it there. When notifications are enabled, use Send me a test notification to check delivery.'),
('notifications', 'Why are phone notifications not arriving', 'Check that notifications are enabled for this device and allowed in browser or phone settings. If permission was denied, allow it in settings and reload the app. Some browsers do not support push notifications; on iPhone, add the app to the Home Screen and open it from there.'),
('notifications', 'How do I manage notifications in the app', 'Open Notifications to review campus alerts. Unread notifications appear first; select one to mark it read, or use the page action to mark all as read. Phone push notifications are configured separately on the same page.'),
('account', 'How do I get an account or change my role', 'There is no public sign-up. The campus administrator creates accounts and assigns roles. Ask your campus administrator if you need an account or if your role, department, club or canteen assignment is incorrect.');
